import{z as i,x as c,o as t,c as p,q as a,j as r,D as o,d as s,s as l,S as d}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"server-based AgentLoop 与 token 级 API","description":"","frontmatter":{"title":"server-based AgentLoop 与 token 级 API","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agentloop-server.md","filePath":"llm/agentloop-server.md","lastUpdated":1791413859000}'),g={name:"llm/agentloop-server.md"};function A(E,e,h,k,m,L){const n=c("Mermaid");return t(),p("div",null,[e[2]||(e[2]=a('<h1 id="server-based-agentloop-与-token-级-api" tabindex="-1">server-based AgentLoop 与 token 级 API <a class="header-anchor" href="#server-based-agentloop-与-token-级-api" aria-label="Permalink to &quot;server-based AgentLoop 与 token 级 API&quot;">​</a></h1><div class="epigraph"><p>Client 与 Server 之间不用 Chat Completions 的文本往返，而走 token 进出的 generate：工具文本再分词不可逆，训练必须用推理引擎当时吐出的 id。</p><footer>—— verl 文档 start/agentic_rl 与 advance/agent_loop：token-in/token-out API</footer></div><p>VeRL 把 HybridFlow 落成可跑的库之后，多轮 agent 把旧的 <strong>SPMD rollout</strong> 撑破：一批请求长度和工具往返次数都不同，再按数据并行轴锁步生成，GPU 在工具 I/O 上齐步空转。v0.7 起默认改成 <strong>rollout server</strong>：推理引擎是在线服务，client 按样本发请求，引擎做动态组批。用户侧的扩展点是 <strong>AgentLoop</strong>——一个可实现的 <code>run</code> 协程，循环调用 <code>LLMServerClient.generate</code>，与环境交互，最后返回 <code>AgentLoopOutput</code>（<code>prompt_ids</code>、<code>response_ids</code>、<code>response_mask</code>）。本篇钉 server 模式要解决的两件事：负载与粘滞会话；以及为什么必须暴露 <strong>token 级 API</strong> 而不是 HTTPS 聊天接口。循环如何把 mask 写对，细节落到 <a href="/llm/multiturn-loss-mask">多轮 loss mask</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SPMD 生成假设：同一时刻所有 DP rank 在做同构的 decode。<span class="marginnote">SPMD（单程序多数据）可以理解为广播体操：所有 GPU 跑同一套动作、听同一声口令齐步走。多轮工具任务里，有的样本早就结束、有的还在等网页返回——齐步走就意味着快的 GPU 站着干等，这就是「锁步」的浪费。</span>多轮工具把这个假设毁掉——有的样本已经结束，有的卡在检索。asyncio 协程可以让 worker 在等工具时去跑别的请求，但若推理仍是「整批 tensor 进 <code>generate</code>」，协程救不了引擎内部的对齐。Server 模式把引擎换成在线服务：每条样本是独立请求，continuous batching 吸收长度差。</p><p>第二问题更隐蔽。Chat Completions 返回文本；下一步把历史文本再 <code>tokenizer.encode</code>。<code>&lt;think&gt;</code>、工具 JSON、前后空白在很多词表上<strong>不是对合</strong>的：模型生成的 token 序列，与「文本再编」的序列可以不同。训练时若用后者算 \\(\\log\\pi(a_t|s_t)\\)，重要性比是在错误动作上算的。verl 文档写明：Client/Server 之间用基于 Ray actor 的 <code>generate</code>，输入输出都是 token id，好让 client 把工具文本与模型 token 的关系自己维护，而不是把不可逆转换藏进 HTTP JSON。</p><h3 id="默认两种-loop-不够用就注册新的" tabindex="-1">默认两种 Loop 不够用就注册新的 <a class="header-anchor" href="#默认两种-loop-不够用就注册新的" aria-label="Permalink to &quot;默认两种 Loop 不够用就注册新的&quot;">​</a></h3><p><code>SingleTurnAgentLoop</code> 覆盖普通单轮 RLVR。<code>ToolAgentLoop</code> 覆盖 ReAct 式多轮工具，数据集需要 <code>agent_name</code> 字段以便分发。自定义环境（浏览器、IDE）应继承 <code>AgentLoopBase</code>，在 <code>run</code> 里写自己的状态机，而不是改 SGLang 内部的 <code>_async_rollout_a_request</code>。历史实现把工具状态塞在 SGLangRollout 里；AgentLoop 把状态提到框架层，引擎只做 token-in-token-out。这与 <a href="/llm/verltool">VERLTool</a> 的工具服务器互补：一个管循环抽象，一个管工具进程。</p><p><span class="marginnote">v0.7 移除 SPMD rollout 是产品决策：维护两套多轮路径的成本高于迁移。旧脚本若仍调 SPMD API 会直接失效，不是「可开关的兼容层」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一步 PPO 仍分 rollout / train 两相（默认同步栅栏时）。Rollout 相：<code>PPOTrainer</code> 抽 batch，<code>AgentLoopManager.generate_sequences</code>；Manager <code>wake_up</code> 所有异步 LLM server，把训练引擎（FSDP / Megatron）权重同步到推理引擎（vLLM / SGLang）；batch 切块发给 <code>AgentLoopWorker</code>；每个 prompt 起一个用户定义的 Loop 协程直到结束。Loop 内部：<code>LLMServerClient.generate(prompt_ids)</code> → 解析动作 → 调环境 → 拼接 token → 再 generate。</p><p><code>LLMServerClient</code> 做两件事。<strong>负载均衡</strong>：第一轮把请求打到当前 inflight 最少的 server。<strong>粘滞会话</strong>：同一 <code>request_id</code> 后续轮固定到同一实例，以便前缀缓存与 TP 组内 KV 还在。换实例等于丢掉 cache，多轮会变成反复 prefill。<span class="marginnote">前缀缓存可以类比「点过的菜不再重做」：同一会话前几轮的 KV 已留在那块 GPU 显存里，粘住同一实例，后续轮只需算新增的一小段；一旦换实例，整个前缀要从头重算一遍（prefill）。50 轮的会话换 50 次实例，等于把前 49 轮白算 50 遍。</span>Server 实现上，SGLang 常在 TP 组的 0 号卡上经 Ray 调 <code>async_generate</code>；vLLM 可用 ZMQ 与 TP 组通信。都要实现同一套：文本 completion（可选）与 <strong>token-in-token-out</strong>。其他引擎实现 <code>AsyncServerBase</code> 即可插入。文档把两种 API 并列，是因为调试时人读文本方便，训练路径却绝不能只走文本。若某个插件只实现了 chat completion，多轮工具任务应视为未接通，而不是「先用着」。训练相仍用 FSDP 或 Megatron 在 token id 上算对数概率；rollout 相交出的 id 必须能直接拼进那次前向，中间不得经过 detokenize。</p>',12)),(t(),r(d,null,{default:o(()=>[l(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22PPOTrainer%22%5D%20--%3E%20M%5B%22AgentLoopManager%22%5D%0A%20%20M%20--%3E%7C%22sync%20weights%22%7C%20S%5B%22AsyncLLMServer%20%C3%97%20N%22%5D%0A%20%20M%20--%3E%20W%5B%22AgentLoopWorker%22%5D%0A%20%20W%20--%3E%20L%5B%22AgentLoopBase.run%22%5D%0A%20%20L%20--%3E%20C%5B%22LLMServerClient.generate%22%5D%0A%20%20C%20--%3E%7C%22sticky%20request_id%22%7C%20S%0A%20%20L%20--%3E%20E%5B%22%E7%8E%AF%E5%A2%83%20%2F%20%E5%B7%A5%E5%85%B7%22%5D%0A%20%20E%20--%3E%20L%0A%20%20L%20--%3E%20O%5B%22AgentLoopOutput%20%2B%20mask%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<h3 id="token-api-的最小契约" tabindex="-1">Token API 的最小契约 <a class="header-anchor" href="#token-api-的最小契约" aria-label="Permalink to &quot;Token API 的最小契约&quot;">​</a></h3><p>输入：已编码的 <code>prompt_ids</code>（以及采样参数）。输出：新产生的 <code>response_ids</code>，<strong>不得</strong>在 server 内再 decode-encode 一轮。工具返回的文本由 Loop 在 client 侧编码成 observation ids，写入序列，并在 mask 上标 0。下一轮 <code>prompt_ids</code> 应是「上一轮完整 token 前缀 + 观察」，而不是「decode 成 messages 再 apply_chat_template」。后者会触发 Agent Lightning v1.0 描述的 retokenization drift。<span class="marginnote">drift 的具体形态：模型生成的 ``标记加前后空白可能是 3 个 token；decode 成文本再 encode 回去，可能变成 2 个——动作的 token 边界挪了位置，本该算在这个动作头上的损失，被算到了别的 token 上，优势估计整个错位。</span>若产品必须走 HTTP 聊天接口，应在代理层保留原始 token（见 <a href="/llm/agent-lightning">Agent Lightning</a>），不能只存文本日志。</p><p><span class="marginnote">粘滞会话与负载均衡有冲突：粘得太死，长尾请求会钉在同一 GPU。第一轮选最空的实例，之后粘住，是折中。极端长尾要用文档中的 stream_mode 调度配方，而不是关掉 sticky。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Server 模式能加速，是因为引擎看到的是请求流而不是「必须等齐的 tensor 批」。这与 <a href="/llm/async-rollout-arch">异步 rollout</a> 的训练–生成重叠是不同层：即使每步训练仍等所有 Loop 结束（同步 PPO），rollout 内部已经异步。Fully async 配方再把 Trainer 与 Rollouter 分节点、加 staleness。先把 AgentLoop 跑对，再开 fully async，否则版本混乱叠加 mask 错误无法调试。</p>',5)),(t(),r(d,null,{default:o(()=>[l(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%20token%20id%20%E5%BA%8F%E5%88%97%22%5D%20--%3E%20B%5B%22%E8%B7%AF%E5%BE%84%E7%94%B2%EF%BC%9Adecode%20%E6%88%90%E6%96%87%E6%9C%AC%20%E2%86%92%20%E5%86%8D%20encode%22%5D%0A%20%20B%20--%3E%20C%5B%22id%20%E5%BA%8F%E5%88%97%E5%8F%AF%E8%83%BD%E6%94%B9%E5%8F%98%EF%BC%9A%E6%A0%87%E7%AD%BE%E4%B8%8E%E7%A9%BA%E7%99%BD%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20C%20--%3E%20D%5B%22logprob%20%E7%AE%97%E5%9C%A8%E9%94%99%E4%BD%8D%E5%8A%A8%E4%BD%9C%E4%B8%8A%EF%BC%8C%E8%AE%AD%E7%BB%83%E6%BC%82%E7%A7%BB%22%5D%0A%20%20A%20--%3E%20E%5B%22%E8%B7%AF%E5%BE%84%E4%B9%99%EF%BC%9A%E4%BF%9D%E7%95%99%E5%8E%9F%E5%A7%8B%20token%20id%22%5D%0A%20%20E%20--%3E%20F%5B%22mask%20%E7%B2%BE%E7%A1%AE%E5%AF%B9%E4%BD%8D%E5%8A%A8%E4%BD%9C%EF%BC%8C%E8%AE%AD%E7%BB%83%E6%AD%A3%E7%A1%AE%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<p><code>wake_up</code> 同步权重是正确性边界。若 Loop 跨一次训练步仍活着（partial rollout），必须定义中断或绑定旧权重，否则同一条 <code>request_id</code> 会在更新后继续 decode。默认同步实现里 Loop 在一步内起止，避免这个问题。打开跨步存活就要按 AReaL 的中断语义来。工具等待期间 GPU 不应被该请求独占：server 把这条请求从 running batch 里摘掉，把算力让给其他 prompt，这才是「为避免等工具而引入协程」的硬件含义。若实现上工具调用仍阻塞整个引擎线程，AgentLoop 只是把 Python 写漂亮了，吞吐不会变。</p><h3 id="和「在推理引擎里写-agent」的差别" tabindex="-1">和「在推理引擎里写 agent」的差别 <a class="header-anchor" href="#和「在推理引擎里写-agent」的差别" aria-label="Permalink to &quot;和「在推理引擎里写 agent」的差别&quot;">​</a></h3><p>SGLang 的 program / OpenAI 工具调用可以在引擎内跑循环，训练框架看不到 token 边界。AgentLoop 把循环拉回 Python，引擎变纯生成器，便于打日志、接沙箱、写单元测试。代价是多一次 RPC。延迟敏感的单 token 工具（本地计算器）RPC 占比高；高延迟检索则可忽略。不要两者各写一半循环。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 Chat Completions 打分再拿文本训练。不要在 Loop 里 <code>decode</code> 后改几个字符再 <code>encode</code> 当模型输出。自定义 Loop 必须返回与训练 batch 对齐的 mask，否则 PPO 会在观察上更新。<code>agent_name</code> 配错会把工具任务送进 SingleTurn，表现为「从不调工具」而不是报错。多 server 的 tokenizer 必须与训练进程字节级一致，包括 special tokens。</p><p>完全异步、工具服务器、harness 代理都建立在「Loop 或等价物交出正确 token」之上。这层错了，上面的加速没有意义。</p><p><span class="marginnote">HybridFlow：Sheng 等 arXiv:2409.19256。实现与 API：verl.readthedocs.io <code>advance/agent_loop</code>、<code>start/agentic_rl</code>；代码 <code>volcengine/verl</code>。vLLM：Kwon 等。SGLang：Zheng 等。Retokenization 问题的展开见 He 等 Agent Lightning v1.0 arXiv:2608.17528。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Server-based AgentLoop 把推理做成在线服务，用协程跑每条样本的多轮循环，避免 SPMD 锁步。</li><li>必须提供 token-in-token-out；文本 API 再分词会破坏 logprob 与优势。</li><li>Client 负责负载均衡与粘滞会话；Loop 负责环境与 mask。</li><li>出处：verl 文档与 HybridFlow 论文；发行说明 v0.7。</li></ul>',9))])}const B=i(g,[["render",A]]);export{_ as __pageData,B as default};
